import { isTransientProp } from './transientProps';

/**
 * Removes Emotion transient props (`$`-prefixed) before spreading onto DOM elements
 * or UI wrapper components. Required when a component receives props from
 * `styled(Component)` variant wrappers.
 */
export const omitTransientProps = <T extends Record<string, unknown>>(
  props: T,
): Omit<T, `$${string}`> => {
  const filtered = {} as Record<string, unknown>;

  for (const [key, value] of Object.entries(props)) {
    if (!isTransientProp(key)) {
      filtered[key] = value;
    }
  }

  return filtered as Omit<T, `$${string}`>;
};
